update stock.stock
set
    available_stock = available_stock - #{quantity},
    locked_stock = locked_stock + #{quantity},
    updated_time = #{updatedTime}
where
    sku_id = #{skuId}
    and available_stock >= #{quantity}

update stock.stock
set
    total_stock = total_stock - #{quantity},
    locked_stock = locked_stock - #{quantity},
    updated_time = #{updatedTime}
where
    sku_id = #{skuId}
    and locked_stock >= #{quantity}

